def leadv(kmax, knee, ex, satk):
    def lp(cycles, kmax=kmax, det=1.0):
        d=det/float(cycles); ps=[]
        for k in range(1,kmax+1):
            a=(1.0/k**0.95)*(1.0/(1.0+(k/knee)**ex))
            ps.append((k,a*0.62,(k*0.9)%6.283)); ps.append((k+d,a*0.46,(k*2.3)%6.283))
